import java.text.DecimalFormat;
import java.util.Scanner;
public class JAverage {
	public static void main(String[] args) {
		//Paso 1: Definir las variables que necesitamos para este programa
		int total = 0;
		int count = 0;
		double average;
		//Paso 2: Leer el primer entero que ingresa el usuario
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese un entero (0 para salir): ");
		int num = scan.nextInt();
		//Paso 3: Procesar el entero que ingreso el usuario, luego recibir y procesar los siguientes enteros mientras el usuario ingrese un entero distinto de cero; de lo contrario, detenerse
		while (num != 0) {
			count++;
			total += num;
			System.out.println("La suma hasta ahora es " + total+", contador = "+count);
			System.out.println("Ingrese un entero (0 para salir): ");
			num = scan.nextInt();   
		}
		scan.close();
		//Paso 4: Calcular e imprimir el promedio de los enteros ingresados por el usuario
		if (count == 0) {
			System.out.println("No se ingresaron enteros.");
		} else {
			average = (double) total / count;
			DecimalFormat fmt = new DecimalFormat("0.###");
			System.out.println("El promedio es " + fmt.format(average));
		}
	}
}

